style.css:
@-moz-document domain("techpowerup.com"), domain("www.techpowerup.com") {
/* ============================================================
     TechPowerUp is a classic server-rendered LIGHT site with NO
     CSS custom-property theme system (only two Swiper vars) — all
     surfaces and text are HARDCODED: white .page (#fdfdfd) content
     on a black body gutter, #333 body text, #115 navy links,
     #445588 blue headings, and the brand #223344 top nav. The
     forums (same host, /forums/) run XenForo with its own white
     surfaces (.p-body / .message / .bbWrapper). We retheme via the
     site's STABLE semantic classes (.page, .contnt, .newspost,
     .s--item, .p-body, .message, ...) since none are hashed, flow
     a GitHub-dark palette through every surface, soften the light
     table/card borders, and keep the TPU blue identity as the
     accent. Semantic colors (green/red/orange spec badges, syntax
     tokens) are preserved.
     ============================================================ */

  :root {
    color-scheme: dark;
  }

  /* ---- Base ---- */
  html,
  body {
    background-color: #14181d !important;
    color: #c4cdd6 !important;
  }

  /* Soften every light border into a subtle dark line */
  *,
  *::before,
  *::after {
    border-color: #262c33 !important;
  }

  /* ---- Main content surfaces (the white .page / .contentbox) ---- */
  .page,
  .contnt,
  .contentArea,
  .contentbox,
  .content,
  #content,
  .main,
  .container,
  .wrap,
  .wrapper {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .page {
    background-color: #14181d !important;
  }

  /* Elevated panels / boxes that carried a white or light-grey bg */
  .contentbox,
  .infobox,
  .sidebar-box,
  .box,
  .panel,
  aside .widget,
  .frontpage-extra,
  .todayslist,
  .todaysfiles,
  .todaysreviews {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  /* ---- Page header (logo bar) ---- */
  .page-header,
  .v-port > span > div,
  header {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
  }

  .page-header {
    border-bottom: 1px solid #262c33 !important;
  }

  /* The site logo is an SVG background-image with a BLACK "TECH"/"UP" wordmark
     that reads on the original white bar but goes near-invisible on the dark
     header. Invert luminance (black → white). hue-rotate(180deg) brings the red
     power button back to a red HUE, but CSS hue-rotate is a linear-matrix
     approximation that desaturates: brand #c20000 lands on salmon (238,106,110).
     saturate(4) brightness(.92) pulls it back to (234,12,23) ≈ the brand red.
     The wordmark is achromatic, so saturate() leaves it untouched. */
  .page-header__logo {
    filter: invert(1) hue-rotate(180deg) saturate(4) brightness(0.92) !important;
  }

  /* Mobile header controls: both toggles are SVG background-images with black
     ink (#231F20 / default fill), invisible on the dark header bar. */
  .navigation-toggle,
  .s--toggle {
    filter: invert(1) !important;
  }

  /* ---- Main nav (TPU brand #223344 → keep the dark-blue identity) ---- */
  nav#menu,
  #menu,
  .p-nav,
  .p-nav-inner {
    background-color: #161d27 !important;
    border-color: #21262d !important;
  }

  nav#menu a,
  #menu a,
  #menu li > span,
  .p-navEl-link {
    color: #d6e2ee !important;
  }

  nav#menu li:hover,
  #menu li:hover,
  nav#menu a:hover,
  .p-navEl-link:hover {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* Dropdown submenus in the nav must stay opaque */
  #menu ul ul,
  #menu li ul,
  .p-nav .menu,
  .menu,
  .menu-content,
  .tooltip,
  .tooltip-content,
  .autoComplete,
  .autoCompleteList {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5) !important;
  }

  #menu ul ul a,
  .menu-content a,
  .menu-content,
  .autoCompleteList a {
    color: #c4cdd6 !important;
  }

  /* XenForo auto-focuses the first row when a nav dropdown opens; the site's
     `.menu-linkRow.is-selected, :hover, :focus` rule then paints it the light
     style's #e8f4fc highlight, so a light-OS user sees a bright plate at the top
     of every menu until they move the pointer. Cover :focus + .is-selected too. */
  #menu ul ul a:hover,
  #menu ul ul a:focus,
  .menu-linkRow:hover,
  .menu-linkRow:focus,
  .menu-linkRow.is-selected,
  .autoCompleteList a:hover,
  .autoCompleteList a:focus {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* Spec-database "Add Filters" floating dropdown (.dropdown-content was a
     white absolutely-positioned panel of blue filter links + value pickers) */
  .dropdown-content,
  .dropdown-content ul,
  .dropdown-content li,
  .js-filter-dropdown .dropdown-content {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .dropdown-content {
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5) !important;
  }

  .dropdown-content a {
    color: #5fb0e6 !important;
  }

  .dropdown-content li:hover,
  .dropdown-content a:hover {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* Selected-filter editor rows (.filter-item) the spec DB inserts into the
     filter bar — each was a white panel of blue value chips + grey counts */
  .filter-item,
  .js-filter-item,
  .filter-options {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  .filter-title,
  .filter-item a,
  .filter-options a {
    color: #5fb0e6 !important;
  }

  .filter-list-item,
  .filter-title-remove-hint {
    color: #8b949e !important;
  }

  /* The site's own modal widget (popup.min.css, `new Popup().Show*`) — the
     sidebar "change timezone" link opens one on EVERY page. Nothing else in the
     theme reaches it: it is appended to <body> at click time and its shell is a
     translucent light-grey frame (rgba(82,82,82,.8)) around a `#popup_content`
     the site paints pure #FFF, so our light body ink lands white-on-white. The
     frame must stay OPAQUE — the page scrolls under it. */
  .popup_container .popup_inner {
    background-color: #161d27 !important;
    background-image: none !important;
    border: 1px solid #2d333b !important;
    box-shadow: 0 12px 32px rgba(0, 0, 0, 0.6) !important;
  }

  .popup_content h2 {
    background-color: #21262d !important;
    border-color: #2d333b !important;
    color: #e6edf3 !important;
  }

  .popup_content #popup_content {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  /* ---- Search / sidebar strip (.s- , light-grey #fafafa) ---- */
  .s-,
  .s---responsive,
  div[class^="s-"][class*="responsive"] {
    background-color: #0d1117 !important;
    border-color: #21262d !important;
  }

  .s--item,
  .s--search,
  .s--login,
  .s--drivers,
  .s--newposts,
  .s--top-rev-s,
  .s--youtube,
  .s--top-news {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .s--item__heading,
  .s--item h1 {
    color: #e6edf3 !important;
  }

  .s--toggle-button {
    color: #c4cdd6 !important;
  }

  /* Sidebar list entries + their hardcoded dark timestamps/dates */
  .s--newposts__list a,
  .s--top-rev-s__list a,
  .s--top-news__list a {
    color: #5fb0e6 !important;
  }

  .s--newposts__time,
  .s--top-rev-s__date,
  .s--top-news__date,
  .s--newposts li time,
  .s--top-rev-s li time {
    color: #8b949e !important;
  }

  /* "Latest GPU Drivers" links are vendor-coloured (#272 green / #991010 red /
     #002d73 navy). The blanket `a:link` rule is (0,1,1) and flattens all three
     to one blue, so re-assert them at (0,2,1) with dark-tuned vendor hues. */
  .s--drivers a.s--drivers__driver--nvidia {
    color: #7ec242 !important;
  }

  .s--drivers a.s--drivers__driver--amd {
    color: #e8585c !important;
  }

  .s--drivers a.s--drivers__driver--intel {
    color: #5fb0e6 !important;
  }

  /* ---- News feed ---- */
  article.newspost,
  .newspost,
  .review-carousel,
  .patreon-previews,
  .featured-news {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  article.newspost {
    border-bottom: 1px solid #21262d !important;
  }

  /* Review LIST page rows (.reviewlist-bit carry a hardcoded #fafafa/#f4f4f4
     alternating card bg; their meta labels are light-grey on that card) */
  .reviewlist-bit,
  .reviewlist-bit.clearfix,
  div.reviewlist-bit {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  .reviewlist-bit .title a {
    color: #cfe2f3 !important;
  }

  .reviewlist-bit .teaser,
  .reviewlist-bit .meta,
  .reviewlist-bit .date,
  .reviewlist-bit .author,
  .reviewlist-bit .category,
  .reviewlist-bit .meta span,
  .reviewlist-bit .meta b {
    color: #8b949e !important;
  }

  .reviewlist-bit .meta a,
  .reviewlist-bit .category a,
  .reviewlist-bit .author a {
    color: #5fb0e6 !important;
  }

  /* Review-list filter bar (.reviewlist-search wraps a light-grey #fafafa
     filter panel of Category / Manufacturer / Award selects) */
  .reviewlist-search,
  .reviewlist-search > div,
  #filtertable,
  #filtertable > div {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  .reviewlist-search label,
  #filtertable label {
    color: #c4cdd6 !important;
  }

  /* Pager / pagination (review list, spec lists) — page-number + prev/next
     are light-grey #f4f4f4 pill links; darken to a button tone */
  .pager a,
  .pager span,
  .prevnext a,
  .pagination a,
  .pagination span,
  nav.pager a {
    background-color: #21262d !important;
    color: #d6e2ee !important;
    border-color: #2d333b !important;
  }

  .pager a:hover,
  .prevnext a:hover,
  .pagination a:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }

  /* `.pager a:hover` above is (0,2,1) — one step ABOVE a bare `.pager .current`
     (0,2,0) — so the current page has to claim its own hover or it flattens
     into an ordinary pill exactly while the pointer is on it. */
  .pager .current,
  .pager .current:hover,
  .pager a.active,
  .pagination .current,
  .pagination .current:hover {
    background-color: #2563a8 !important;
    color: #ffffff !important;
  }

  .pager a.disabled,
  .prevnext a.disabled {
    color: #7d8590 !important;
  }

  /* The pager's non-control spans ("1 to 25 of 6263", "Go to Page") and the
     .buttons wrapper are plain LABELS the site leaves bare; the `.pager span`
     rule above paints them into the same pill as the page links, so a label
     reads as a clickable button. Reset them back to bare text. */
  .pager > span.counts,
  .pager > span.description,
  .pager > span.buttons {
    background-color: transparent !important;
    border-color: transparent !important;
    color: #8b949e !important;
  }

  /* Review-article header "Discuss in our Forums" chip: a #f6f6f6 plate whose
     two labels are ::before/::after text (#444 / #999) and whose speech-bubble
     background SVG is #FAFAFA-filled, so it survives on a dark plate. */
  .discuss {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
    color: #5fb0e6 !important;
    opacity: 1 !important;
  }

  .discuss::before {
    color: #e6edf3 !important;
  }

  .discuss::after {
    color: #8b949e !important;
  }

  .discuss:hover {
    background-color: #21303f !important;
    border-color: #3d4450 !important;
  }

  /* The strip that closes every review article page ("View as single page", the
     page picker and the Next Page CTA) is a #fafafa slab under a dotted rule. */
  .review .contnt > footer {
    background-color: #1c2128 !important;
  }

  /* Review "one page" nav strip + the image-comparison widget's white controls */
  .onepage-nav,
  .image-comparison2__toggle-fullscreen,
  .image-comparison2__zoom {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }

  .image-comparison2__zoom:hover {
    background-color: #21303f !important;
  }

  /* Article body image placeholders (light-grey #ddd sizing box behind figures) */
  .responsive-image-xx,
  [class*="responsive-image"] {
    background-color: transparent !important;
  }

  /* Article post date / generic <time> — site paints a hardcoded dark grey
     (#404040) that turns invisible on the dark surface */
  time,
  .post-date,
  .newspost time,
  .contnt time {
    color: #8b949e !important;
  }

  /* Carousel + featured-news tiles carry a hardcoded light tile bg */
  .review-carousel__items,
  .review-carousel-item,
  .review-carousel-item__title,
  .featured-news__item,
  .featured-news__image,
  .featured-news__title,
  .patreon-previews__item {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  .review-carousel-item__title,
  .featured-news__title,
  .featured-news__item-title {
    color: #cfe2f3 !important;
  }

  /* Carousel item separators are a 3px full-height ::before painted #ccc —
     a light hairline between each tile; darken to a subtle divider line */
  .review-carousel-item::before,
  .review-carousel-item::after {
    background-color: #262c33 !important;
  }

  .featured-news__image {
    background-color: #161d27 !important;
  }

  /* Colored category / deal flags keep their tinted identity but are deepened
     so white labels stay legible on the dark theme. The site ships ELEVEN
     semantic variants (news.css `.flags .flag.*`) PLUS the plain category tags
     (Motherboards, Memory, CPU Coolers, …) which TPU colours per-category via an
     INLINE `background-color:#…` (orange/blue/purple/…). Match the site's own
     `.flags .flag` (0,2,0) WITHOUT !important for the neutral fallback: it wins
     over the site's `gray` by source order for uncategorised tags, while the
     inline category colour (1,0,0,0) still shows through — keeping the category
     colour-coding — and each `.flag.*` modifier below wins via its !important. */
  .flag,
  .flag span,
  span.flag {
    color: #ffffff !important;
  }

  .flags .flag {
    background-color: #3d4450;
  }

  .flag.draft {
    background-color: #6b4a12 !important;
  }

  .flag.pr {
    background-color: #21303f !important;
  }

  .flag.featured {
    background-color: #7d2a2c !important;
  }

  .flag.editorial {
    background-color: #2a5c2d !important;
  }

  .flag.updated {
    background-color: #2a6363 !important;
  }

  .flag.review {
    background-color: #6b3823 !important;
  }

  .flag.article {
    background-color: #6b6224 !important;
  }

  .flag.sponsored {
    background-color: #6e5d27 !important;
  }

  .flag.live {
    background-color: #a51414 !important;
  }

  .flag.ces,
  .flag.computex {
    background-color: #6e2c74 !important;
  }

  .flag.video {
    background-color: #8c1312 !important;
  }

  /* Download-page version badge: `.flag.latest` marks the newest release in a
     GREEN pill (#497d2a). Our broad `.latest` downloads-tile rule below paints
     it #1c2128 with !important, erasing the signal — reclaim it at (0,2,0). */
  .flag.latest {
    background-color: #2a5c2d !important;
  }

  /* Front-page poll widget (white card) */
  .frontpagepoll,
  .frontpagepoll .poll,
  aside.frontpagepoll {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }

  .frontpagepoll label,
  .frontpagepoll li,
  .frontpagepoll .pollanswer {
    color: #c4cdd6 !important;
    background-color: transparent !important;
  }

  /* Poll RESULT bars: the #dfe3ef track is a ~14px-tall light strip (under the
     audit size floor); the #5a6fb1 fill inside it is the data and stays. */
  .frontpagepoll ul.results .bar,
  .newspoll > ul.results > li .bar {
    background-color: #21262d !important;
  }

  .newspoll_btn::before {
    color: #8b949e !important;
  }

  /* The "Quick Poll" opener is a raster PNG button (a light-grey plate with dark
     ink and an orange "?" bubble) — a bright speck on the dark article header and
     unreachable by any background-color rule. Invert it the same way as the logo:
     plate → dark, label → light; hue-rotate/saturate keep the "?" bubble orange. */
  .newspoll_btn {
    filter: invert(1) hue-rotate(180deg) saturate(1.6) brightness(0.95) !important;
  }

  /* "Today's Reviews" list separators are a `content:"-"` ::after painted #555 */
  .todayslist ul > li::after {
    color: #8b949e !important;
  }

  /* Pinned / featured news tiles (#f8f8f8 cards, #ddd image wells) and their
     `> a:hover` which the site flips to pure WHITE */
  .pinned-news__item,
  .pinned-news2__item,
  .pinned-news2__image {
    background-color: #1c2128 !important;
  }

  /* news.css hovers these tiles with `background-color:#fff; outline:2px solid #ccc`.
     We already repaint the background, but nothing reads `outline` — so every
     hovered tile still drew a bright grey 2px ring on the dark page. */
  .featured-news__item > a:hover,
  .pinned-news__item > a:hover,
  .pinned-news2__item > a:hover {
    background-color: #21303f !important;
    outline-color: #2f74c0 !important;
  }

  .pinned-news__title,
  .pinned-news2__item-title {
    color: #cfe2f3 !important;
  }

  /* "Up next" strip (#f9d8d8 pink) and the sitewide yellow notice bar
     (#ffeaa8 + a tiled PNG stripe background-image) */
  .upnext {
    background-color: #3a2020 !important;
    border-color: #5c3030 !important;
  }

  .infobar {
    background-color: #3a2f10 !important;
    background-image: none !important;
    border-bottom-color: #6e5d27 !important;
  }

  /* The notice text IS an <a>, so `.infobar__link` (0,1,0) would lose to the
     blanket `a:link` (0,1,1) rule; scope it under `.infobar` to win at (0,2,1). */
  .infobar,
  .infobar a.infobar__link {
    color: #e3c46a !important;
  }

  .infobar a.infobar__link:hover {
    color: #ffe08a !important;
  }

  /* Tag cloud on news articles (#f8f8f8 pills) */
  .tagcloud a {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  .tagcloud a:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }

  /* Every news headline is prefixed by a vendor-logo PNG in an 87px `.newsicon`
     plate the site paints #fafafa — 30+ of the brightest squares on the page.
     The logos are transparent PNGs whose ink runs from pure black (AMD, MSI,
     Steam) through full colour (NVIDIA green, Xbox, Microsoft), so a dark plate
     erases the black ones and no filter keeps the coloured ones honest. The
     plate has to stay light; mute it to the theme's light-ink tone instead,
     which drops its luminance ~40% and leaves every logo legible. */
  .newsicon {
    background-color: #c9d1d9 !important;
  }

  /* The Patreon strip's category tag falls back to a #848484 plate when the
     entry has no category, and TPU sets the per-category colour INLINE. Match
     the `.flags .flag` treatment: deepen the fallback WITHOUT !important at
     (0,1,0) so we beat the site's own default by source order while the inline
     category colour still shows through. The tag's white ink is the site's. */
  .patreon-previews__tag {
    background-color: #3d4450;
  }

  /* The Patreon strip's scrollbar is painted white by a ::-webkit-scrollbar rule
     (the `scrollbar-color` shorthand at the end of this sheet is Firefox-only) */
  .patreon-previews__list-wrapper::-webkit-scrollbar {
    background-color: #14181d !important;
  }

  .patreon-previews__list-wrapper::-webkit-scrollbar-thumb {
    background-color: #2d333b !important;
  }

  .newspost h2,
  .newspost h1,
  .newspost-title {
    color: #e6edf3 !important;
  }

  /* Date separator (brand blue #445588 bar) */
  .datesep {
    background-color: #21303f !important;
    color: #d6e2ee !important;
    border-color: #2d333b !important;
  }

  /* News-article on-page comments (TPU's native .forumpost markup, distinct
     from the XenForo .message posts) — the comment card (#f0f0f0), its
     .posttext body (#fdfdfd) and the `<footer>` carrying the post time (#fdfdfd)
     shipped white with washed-out text */
  section.comments article.forumpost,
  article.forumpost.clearfix,
  .forumpost,
  .forumpost > footer,
  .forumpost .posttext,
  .posttext {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  .forumpost header.userinfo {
    background-color: #161d27 !important;
    border-color: #21262d !important;
  }

  .forumpost .username,
  .forumpost .userinfo a {
    color: #cfe2f3 !important;
  }

  /* Hardcoded #666 user titles ("News Editor", "Linux Advocate") on the dark header */
  .forumpost .usertitle,
  .usertitle {
    color: #8b949e !important;
  }

  /* ---- Headings (site uses #445588 / #115 blue) ---- */
  h1,
  h2,
  h3,
  h4,
  h5,
  h6 {
    color: #e6edf3 !important;
  }

  .contnt h1,
  .contnt h2,
  .text h2,
  .text h3 {
    color: #cfe2f3 !important;
  }

  /* ---- Body / article reading surface ---- */
  .text,
  .text p,
  .text li,
  .text td,
  p,
  li,
  dd,
  dt,
  span,
  label {
    color: #c4cdd6 !important;
  }

  small,
  .small,
  .muted,
  .meta,
  .date,
  .byline,
  .newspost .meta {
    color: #8b949e !important;
  }

  /* Quotes anywhere (news posts, articles) */
  blockquote {
    background-color: #161d27 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* On the news side a quote's 4px left bar is its marker — the panel tint the
     site pairs it with (#f6f6f6 / #f2f2f2) is a hair off the surface once dark,
     so the greyed bar leaves the quote reading as plain body copy. XenForo's
     quote block has no such bar and keeps the amber attribution row instead. */
  .newspost blockquote,
  .posttext blockquote {
    border-left-color: #2f74c0 !important;
  }

  /* ---- Links (navy #115 → readable accent blue) ---- */
  a,
  a:link,
  a:visited {
    color: #5fb0e6 !important;
  }

  a:hover {
    color: #9bd4ff !important;
  }

  /* Link text the site wraps in a <span>/<b> (schema.org breadcrumbs, news
     headlines, spec-DB crumbs) is matched DIRECTLY by our broad `span` / `.contnt b`
     body rules — they win on the child element, so the anchor's blue never reaches
     the glyphs and the link reads as plain body copy, indistinguishable from the
     current crumb beside it. Hand the anchor's own colour back down to its children
     (class-scoped children like `.flag span` keep winning on specificity). */
  a span,
  a b,
  a strong,
  a em,
  .contnt a b,
  .page a b {
    color: inherit !important;
  }

  /* The news-search box (magnifier on the `.datesep` bar) wraps every matched
     word in `span.highlight`, a `#ff8` plate built for the site's black body
     ink. Our light ink lands ~1.5:1 on it and inside a headline the anchor blue
     lands ~2.1:1, so the exact words the reader searched for are the least
     legible on the page. `span.highlight` is (0,1,1) — it outranks both the
     blanket `span` ink and the `a span` inherit-reclaim above, so the marker
     keeps its own ink inside a link as well as in body copy. */
  span.highlight,
  .highlight {
    background-color: #6b5d10 !important;
    color: #ffe08a !important;
  }

  /* Keep nav / header / footer link colors handled by their own blocks above */
  .page-header a,
  nav#menu a,
  #menu a {
    color: inherit !important;
  }

  /* ---- Tables (spec databases + review tables: dense, light borders) ---- */
  table,
  table.items-desktop-table,
  .tablesorter,
  .drvtbl {
    background-color: transparent !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  th,
  thead th,
  table.items-desktop-table th,
  thead tr,
  .colheader,
  .colheader tr,
  tr.colheader {
    background-color: #1c2128 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* Spec-table header cells keep their brand-navy bg via inline style on some
     pages; force the label (and its inner spans) to a bright readable tone */
  th,
  th span,
  thead th span {
    color: #e6edf3 !important;
  }

  td {
    border-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  /* Zebra striping + row hover */
  tr:nth-child(even) td,
  tr:nth-child(even),
  .even td,
  .alt td {
    background-color: #171c22 !important;
  }

  tr:nth-child(odd) td,
  .odd td {
    background-color: transparent !important;
  }

  tbody tr:hover td,
  table.items-desktop-table tbody tr:hover {
    background-color: #21303f !important;
  }

  /* Spec-table section headers / group rows TPU paints blue */
  .tablesorter caption,
  table caption,
  .group td,
  td.group {
    background-color: #21303f !important;
    color: #d6e2ee !important;
  }

  /* GPU/CPU spec database + review spec tables.
     The site paints the zebra AND the 7px vendor colour stripe
     (`linear-gradient(to right, red 7px, transparent 7px)`) on the <tr>, and
     leaves every <td> transparent. Painting the td opaque therefore covers the
     stripe and flattens the zebra to one flat tone — so keep tds transparent
     and drive both the stripe and the alternation from the row. */
  .items-desktop-table tbody tr,
  .contnt table tbody tr,
  table tbody tr[style],
  tr[class*="vendor-"] {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .items-desktop-table tbody tr:nth-child(odd),
  .contnt table tbody tr:nth-child(odd) {
    background-color: #171c22 !important;
  }

  .items-desktop-table tbody tr td,
  .contnt table tbody tr td,
  tr[class*="vendor-"] td {
    background-color: transparent !important;
  }

  .items-desktop-table tbody tr:hover,
  .contnt table tbody tr:hover,
  tr[class*="vendor-"]:hover {
    background-color: #21303f !important;
  }

  .items-desktop-table tbody tr:hover td,
  .contnt table tbody tr:hover td,
  tr[class*="vendor-"]:hover td {
    background-color: transparent !important;
  }

  /* Spec-DB group / generation header rows (#555 label on a light band) */
  .generation-header,
  .generation-header-mobile {
    background-color: #21262d !important;
    color: #8b949e !important;
  }

  /* The DESKTOP generation header paints its #e8e8e8 band as a background-IMAGE
     (`linear-gradient(to right, transparent 7px, #e8e8e8 7px)` — the 7px transparent
     lead-in is the gap the row's vendor colour stripe shows through), so the
     background-COLOR rule above never clears it and the band renders white with our
     near-white heading text on it. Rebuild the same gradient in the button tone and
     keep the stripe gap. Two classes so this also outranks `table.items-desktop-table
     th` (0,1,2) above, which is what actually paints these cells today. */
  .items .generation-header,
  .items-desktop-table .generation-header,
  .processors .generation-header {
    background-color: transparent !important;
    background-image: linear-gradient(to right, rgba(0, 0, 0, 0) 7px, #21262d 7px) !important;
    color: #8b949e !important;
  }

  /* "Recent changes" / sidebar info widgets on spec pages (light inner box) */
  aside.changes,
  aside.changes > div,
  .changes,
  .changes > div {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }

  /* Released-date + secondary spec cells (were light-grey #c4c4c4 on light) */
  .item-released,
  td .item-released,
  .items-desktop-table td {
    color: #c4cdd6 !important;
  }

  .item-released {
    color: #8b949e !important;
  }

  /* ---- GPU/CPU spec DETAIL pages (newer .gpudb / section.details layout) ----
     A single card's page (e.g. /gpu-specs/<card>) is built from white
     section.details cards, light-grey #f3f3f3 summary chips, dl.clearfix
     spec lists and a relative-performance panel — none covered by the
     spec-LIST rules above. Dark every surface; keep the blue section headers. */
  .sectioncontainer,
  section.details,
  section.details > div,
  section.details dl,
  section.details dl.clearfix,
  dl.clearfix,
  section#boards,
  section#boards > div,
  section#boards > div > div,
  .gpudb-relative-performance__outer,
  .gpudb-relative-performance__wrap,
  .gpudb-relative-performance-entry {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  /* Zebra the relative-performance rows (kept the periwinkle data bars intact) */
  .gpudb-relative-performance-entry:nth-child(even) {
    background-color: #171c22 !important;
  }

  /* Relative-performance entry titles: the current card's row paints its title
     in the site's dark brand navy (#455588) and any plain title text is #666 —
     both go dark-on-dark on the card. Lift them; the other rows' titles are
     blue <a> links handled by the link rule and stay as-is. */
  .gpudb-relative-performance-entry__title {
    color: #c4cdd6 !important;
  }

  .gpudb-relative-performance-entry--primary .gpudb-relative-performance-entry__title,
  .gpudb-relative-performance-entry--highlight .gpudb-relative-performance-entry__title {
    color: #e6edf3 !important;
  }

  /* The percentage beside each bar is the chart's one readable number and the
     site hardcodes it #888 — under 4.5:1 on the card, worse on the amber
     highlight row. It is a <div>, so no broad text rule ever reached it. */
  .gpudb-relative-performance-entry__number {
    color: #c4cdd6 !important;
  }

  /* The row for the card you are actually viewing carries `--highlight` (NOT
     `--primary`, which the site also sets) and a #fbf1cb amber tint. The
     entry rule above would flatten it into every other row, erasing the only
     row-level "you are here" signal. Restore it as a dark amber. The site
     declares its tint `!important` at (0,1,0), so match on both classes to
     win on specificity rather than on injection order. */
  .gpudb-relative-performance-entry.gpudb-relative-performance-entry--highlight {
    background-color: #332d1a !important;
  }

  /* Same "current record" tint elsewhere in the databases: the custom-board row,
     and the active entry in the all-GPUs / GPU-history lists (#e0eaf7) */
  .customboard-current,
  .customboard-current td {
    background-color: #332d1a !important;
  }

  .all-gpus__entry-active,
  .gpu-history__entry-active {
    background-color: #21303f !important;
  }

  .customboards .sort-key {
    background-color: #21262d !important;
  }

  /* Review comparison tables (`.tputbl.hilight`) mark the row for the product
     being reviewed with `tr.active` + a #fbf2c2 cream tint — the "you are here"
     signal in a long CPU/GPU spec-comparison list. Our zebra `tr:nth-child(*) td`
     rules (0,1,1 !important) paint every cell, erasing it; reclaim the row at
     (0,2,1) with the same dark amber the DB highlight rows use. */
  .tputbl tr.active > td,
  .tputbl tr.active > th,
  .hilight tr.active > td,
  .hilight tr.active > th {
    background-color: #332d1a !important;
  }

  /* Unreleased / estimated / unverified warning panels (#f9d8d8, #f2dede) */
  .gpudb-unreleased,
  .gpudb-estimated-specs,
  .gpudb-warning,
  .cpudb-details .unreleased,
  .ssddb-details .unreleased,
  .bios-unverified-warning {
    background-color: #2d1a1a !important;
    border-color: #7d2a2c !important;
    color: #e0b7b7 !important;
  }

  .gpudb-unreleased *,
  .gpudb-estimated-specs *,
  .gpudb-warning * {
    color: #e0b7b7 !important;
  }

  /* Multi-GPU "yes" pill is a light-green ::after badge */
  .gpudb-details section.details .multigpu::after {
    background-color: #182a1a !important;
    color: #7ee787 !important;
  }

  /* Add-Filters flyout internals: the value list, its buttons row, and the
     SELECTED value chip (#ebeff2) all shipped white */
  .filter-list-item,
  .filter-list-buttons {
    background-color: #1c2128 !important;
  }

  .filter-list-item:hover,
  .filter-list-item.is-selected:hover {
    background-color: #21303f !important;
  }

  .filter-list-item-items > a.is-selected,
  .filter-options > a.is-selected {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* Capacity / image chips in the CPU, SSD and VGA-BIOS list tables */
  .items .item-capacity,
  .drives .drive-capacity {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  .items .item-capacity:hover,
  .drives .drive-capacity:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }

  /* Under ~600px the spec databases drop their <table> entirely and re-render
     every row as a CARD (`items-mobile--item` on GPU/CPU, `drives-mobile--drive`
     on SSD/VGA-BIOS). The card carries its OWN #f4f4f4 background, so the
     desktop table rules never reach it and the whole list reads as white plates
     under the sitewide light ink. Desktop-only review cannot see this. */
  .items-mobile--item,
  .drives-mobile--drive,
  .drives-desktop-table {
    background-color: #1c2128 !important;
  }

  /* Product-photo wells: every source is an opaque JPG, so the #fff plate is
     only ever visible while the lazily-loaded image is still in flight —
     a white flash per tile down a 200-row list. */
  .items .item-image,
  .drives .drive-image,
  .vgabios-details .cardimage {
    background-color: #21262d !important;
  }

  /* Review-database popularity bars: the #dfe3ef track is a 50x12 strip (below
     the audit size floor); the blue fill inside it is the data and stays. */
  .reviews-container .clicks > .bar-wrap {
    background-color: #21262d !important;
  }

  /* Disambiguation list shown when a GPU lookup matches several cards */
  .gpu-lookup-multiple-found .entry {
    background-color: #1c2128 !important;
  }

  .gpu-lookup-multiple-found .entry:hover {
    background-color: #21303f !important;
  }

  /* Staff-flagged BIOS rows keep their amber "needs attention" tint */
  .vgabios .contnt table.bioslist .staff-only {
    background-color: #332d1a !important;
  }

  /* Image filmstrip caption pills (Back / PCB Front / PCB Back) overlay each
     thumbnail with a hardcoded #f5f5f5 pill + dark #443b3b label — audit-blind
     (short <40px pills) and a bright eyesore on the dark thumbnails */
  .gpudb-filmstrip__title,
  .ssddb-filmstrip__title,
  .chip-image--type,
  .drive-image--type,
  [class*="filmstrip"] [class*="title"] {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }

  /* Top summary chips: the GPU DB uses dl.gpudb-specs-large / __entry (#f3f3f3
     box, #555 text); the CPU DB uses a plainer .specs-large > div grid where
     the value is bare text and the label is a nested <div> — both went white */
  dl.gpudb-specs-large,
  .gpudb-specs-large__entry,
  .specs-large > div {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }

  .gpudb-specs-large__value,
  .specs-large > div {
    color: #e6edf3 !important;
  }

  .gpudb-specs-large__title,
  .specs-large > div > div {
    color: #8b949e !important;
  }

  /* Spec list dt/dd inside the detail cards stay readable on the dark card */
  section.details dt,
  dl.clearfix dt {
    color: #8b949e !important;
  }

  section.details dd,
  dl.clearfix dd {
    color: #c4cdd6 !important;
  }

  /* ---- Downloads section (/download) ---- the category tree (.tree-wrap /
     .dltree) and the Popular/Latest tiles (.popular a.clearfix / .latest)
     all carried a hardcoded light #f8f8f8 card bg */
  .tree-wrap,
  .dltree,
  .dltree li,
  .dltree li.root,
  .popular,
  .popular a.clearfix,
  .latest,
  .latest > div {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  .popular a.clearfix:hover,
  .dltree li a:hover {
    background-color: #21303f !important;
  }

  /* Currently-selected node in the downloads category tree (#cadbe5 pale blue).
     The site sets this with `!important` at (0,5,4), so a short selector loses
     even with our own `!important` — mirror its chain and add one class. */
  .downloads .contnt > .dl-left > nav ul.dltree li > a.selected.selected {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* Downloads CATEGORY pages (/download/<category>/) — an entirely separate
     layout from the index and the detail page: a #fdfdfd/#fafafa alternating
     row list, a #f3f3f3 sort bar, and a green #b2eca3 hint. Untouched before,
     so every row shipped white with our near-white headings on top of it. */
  .download-list > a.download,
  .download-list > a.download:nth-child(odd),
  .sort-options {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  .download-list > a.download:hover {
    background-color: #21303f !important;
  }

  .latest a:nth-child(odd) {
    background-color: #171c22 !important;
  }

  .download-hint {
    background-color: #182a1a !important;
    color: #7ee787 !important;
  }

  /* Download DETAIL extras: the selected version row (#fefced cream), the hash
     panel, the "Get Notified" CTA (#f0e588) and the mirror-list hover */
  .versions .files > li.selected {
    background-color: #332d1a !important;
    box-shadow: none !important;
  }

  .versions .files .hashes {
    background-color: #0d1117 !important;
  }

  .downloads-details .notification > .button {
    background-color: #6e5d27 !important;
    border-color: #8a7433 !important;
    color: #ffffff !important;
  }

  /* Its label is a nested <span>, so the broad `span` body rule wins on the
     child and greys it to ~4:1 on the gold face. */
  .downloads-details .notification > .button span {
    color: #ffffff !important;
  }

  .downloads-mirrors .mirrorlist > button:hover {
    background-color: #2d333b !important;
  }

  /* Download DETAIL page (/download/<app>): versions box, file rows, the
     social/actions bar, the "Get Notified" form and the Version History
     changelog all carried light (#eaf1e9 / #f8f8f8 / #f4f1da / #f4f4f4) bg */
  .versions,
  .version,
  .files li.file,
  .actions,
  .actions.clearfix,
  .history,
  .history-entries,
  .history-entry,
  form.notification {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    color: #c4cdd6 !important;
  }

  /* Hardcoded #555/#777 secondary labels on download cards (file name, file
     size, total downloads) go invisible on the now-dark surface */
  .filename,
  .filesize,
  .downloaded {
    color: #8b949e !important;
  }

  /* Two more light form panels the earlier rules never claimed: the VGA-BIOS
     collection's "Refine Search Parameters" box (a #fafafa slab whose labels are
     a pale grey that vanishes on it) and the GPU-Z page's validation-ID lookup
     strip (#eee, same washed-out labels). */
  section.search,
  section.search > div,
  form.validationlookup {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  section.search label,
  form.validationlookup,
  form.validationlookup label {
    color: #c4cdd6 !important;
  }

  /* Category index pages use bold tags (#333) on light tiles */
  .contnt b,
  .page b,
  .alphabet b,
  .index b {
    color: #c4cdd6 !important;
  }

  /* ---- Forms / inputs / search box ---- */
  input,
  input[type="text"],
  input[type="search"],
  input[type="email"],
  input[type="password"],
  input[type="number"],
  textarea,
  select,
  .input,
  .button--icon,
  .s--search__form input {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
  }

  /* The sidebar search's submit is a 25px TRANSPARENT hit-area absolutely
     positioned over the magnifier glyph, which the site paints as a
     background-image on the INPUT. The button rules below fill it with a solid
     grey plate that juts past the field and hides the glyph. This selector is
     (0,2,1): it out-ranks the resting `input[type="submit"]` (0,1,1) but only
     TIES `input[type="submit"]:hover`, so the hover state must be named
     explicitly rather than relying on source order. */
  .s--search__form input.s--search__submit,
  .s--search__form input.s--search__submit:hover {
    background-color: transparent !important;
    border: 0 !important;
  }

  /* That magnifier glyph is a 12px paletted PNG whose ink is a flat #404040 —
     built for the field's white face, it lands at ~1.8:1 on the dark input and
     all but vanishes. Restate it as a light vector; the site's own
     `background-position: right 7px center` still places it, but an SVG with no
     intrinsic size stretches to the box, so pin `background-size` to 12px. */
  .s--search__form input.s--search__input {
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 12 12'%3E%3Cg fill='none' stroke='%238b949e' stroke-width='1.5'%3E%3Ccircle cx='4.9' cy='4.9' r='3.4'/%3E%3Cpath d='M7.6 7.6 L11 11' stroke-linecap='round'/%3E%3C/g%3E%3C/svg%3E") !important;
    background-size: 12px 12px !important;
  }

  input:focus,
  textarea:focus,
  select:focus,
  .input:focus {
    border-color: #5fb0e6 !important;
    outline: none !important;
  }

  input::placeholder,
  textarea::placeholder,
  .input::placeholder {
    color: #8b949e !important;
    opacity: 1 !important;
  }

  input::-webkit-input-placeholder,
  textarea::-webkit-input-placeholder {
    color: #8b949e !important;
  }

  /* The forum's password-strength bar is a native <meter>: its TRACK is painted
     by a UA shadow pseudo, not by the element's own background, so no
     background-color rule reaches it and XenForo's light-style trough renders as
     a full-width near-white strip across the register / password forms. The
     value fill (green / yellow / red) is the strength signal and stays theirs. */
  meter.meterBar {
    background-color: #21262d !important;
  }

  meter.meterBar::-webkit-meter-bar {
    background-color: #21262d !important;
  }

  /* ---- Buttons ----
     `.button` ships `text-shadow: 1px 1px 0 #fff` for its light-grey face; on a
     dark button that white shadow outlines every glyph. Reset it explicitly —
     neither `color` nor `background` clears it. */
  button,
  .btn,
  .button,
  .search-button,
  input[type="submit"],
  input[type="button"] {
    background-color: #21262d !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border: 1px solid #2d333b !important;
    text-shadow: none !important;
  }

  button:hover,
  .btn:hover,
  .button:hover,
  input[type="submit"]:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }

  /* Primary / CTA buttons keep a blue identity. `.startbutton` is the big blue
     download CTA (#4486c7) on every /download/<app> page — the base `.button`
     rule above would otherwise flatten it into the same neutral grey. */
  .btn-primary,
  .button.inverted,
  .submitUnit button[type="submit"],
  .button.startbutton,
  input.startbutton {
    background-color: #2563a8 !important;
    border-color: #2f74c0 !important;
    color: #ffffff !important;
  }

  .btn-primary:hover,
  .button.inverted:hover,
  .button.startbutton:hover,
  input.startbutton:hover {
    background-color: #2f74c0 !important;
  }

  /* `.downloadbutton` is the "Download Now" CTA on every /vgabios/<id>/ page —
     the site's own #3072b3 blue gradient, flattened by the base `.button` rule
     into the same grey as the secondary "Find compatible BIOS" beside it. Its
     label is an <a>, so the ink needs (0,2,1) to beat the blanket `a:link`;
     the site's white inset gloss was built for the blue face and reads as a
     bright rim on grey, so it goes with the plate. */
  a.button.downloadbutton,
  .buttons > .downloadbutton {
    background-color: #2563a8 !important;
    background-image: none !important;
    border-color: #2f74c0 !important;
    box-shadow: none !important;
    color: #ffffff !important;
    text-shadow: none !important;
  }

  a.button.downloadbutton:hover,
  .buttons > .downloadbutton:hover {
    background-color: #2f74c0 !important;
    border-color: #2f74c0 !important;
  }

  /* ---- XenForo button VARIANTS (the /forums/ half of the domain) ----
     TPU's forum paints a hierarchy the base `.button` rule above flattens: the
     plain button is blue, `--primary` a brighter blue, `--cta` ORANGE (not
     blue), `--plain` a bare glyph with no plate at all, and `is-disabled` a
     muted face. At (0,1,0) the base rule swallows all of them, so the login
     form's primary submit, the mobile nav trigger and a disabled control all
     render as one identical neutral chip. Reclaim each at (0,2,0) — which also
     has to out-rank the sitewide `a:link` blue (0,1,1), since every one of
     these variants is an <a> as often as a <button>. */
  .button.button--primary {
    background-color: #2563a8 !important;
    border-color: #2f74c0 !important;
    color: #ffffff !important;
  }

  .button.button--primary:hover,
  .button.button--primary:focus {
    background-color: #2f74c0 !important;
    color: #ffffff !important;
  }

  /* `--cta` is the forum's ORANGE call to action (#f2930d light / #a5660d dark);
     painting it our blue both loses the hue and — once `a:link` wins the ink on
     the anchor form — leaves blue-on-blue at ~2.8:1. */
  .button.button--cta {
    background-color: #a4620d !important;
    border-color: #c8791a !important;
    color: #ffffff !important;
  }

  .button.button--cta:hover,
  .button.button--cta:focus {
    background-color: #c8791a !important;
    color: #ffffff !important;
  }

  /* The BBCode spoiler reveal is a FILLED blue control in both of the forum's
     own schemes (#165988), not the plateless base `.button` — the base rule
     above flattens it into the neutral chip. */
  .button.bbCodeSpoiler-button {
    background-color: #2563a8 !important;
    border-color: #2f74c0 !important;
    color: #ffffff !important;
  }

  .button.bbCodeSpoiler-button:hover,
  .button.bbCodeSpoiler-button:focus {
    background-color: #2f74c0 !important;
    color: #ffffff !important;
  }

  /* `--plain` is a plate-less text/glyph button — the mobile nav trigger is one.
     Giving it the neutral chip boxes a bare hamburger into a grey square. */
  .button.button--plain {
    background-color: transparent !important;
    border: 0 !important;
  }

  /* A disabled control must not read as an enabled one */
  .button.is-disabled,
  .button.is-disabled:hover {
    background-color: #1a1f25 !important;
    border-color: #262c33 !important;
    color: #7d8590 !important;
  }

  /* The review pager's "Next Page »" CTA carries the next section's name in a
     nested <small>, which the blanket `small` rule (0,0,1) paints muted grey —
     ~2:1 on the blue CTA face. Claim it at (0,1,1) with a tint that clears 4.5:1
     on both the blue CTA and the neutral button. */
  .button small {
    color: #cfe2f3 !important;
  }

  /* Destructive variant: the base `.button` rule above would otherwise erase
     its #900 label into the same neutral grey as every other button */
  .button.danger {
    color: #ff7b72 !important;
  }

  .button.danger:hover,
  .button.danger:focus,
  .button.danger:active {
    background-color: #8c2b26 !important;
    color: #ffffff !important;
  }

  /* Review-carousel prev/next: a #ddd plate carrying a BLACK arrow SVG as a
     background-image. Darkening the plate would erase the arrow, so invert the
     whole control (plate → #222, arrow → white) in one pass. */
  .review-carousel__button {
    filter: invert(1) !important;
  }

  /* ---- Code / pre (forum BBCode + any inline code) ---- */
  pre,
  code,
  kbd,
  samp,
  .bbCodeBlock,
  .bbCodeBlock-content,
  .bbCodeCode,
  .code {
    background-color: #0d1117 !important;
    color: #c9d1d9 !important;
    border-color: #2d333b !important;
  }

  pre,
  .bbCodeBlock {
    border: 1px solid #2d333b !important;
  }

  /* Prism syntax tokens are <span>s, so the blanket `span` body rule (0,0,1
     !important) beats every token colour the forum ships and a code block
     renders as one flat grey. These are the values XenForo's own dark style
     uses, restated at (0,3,0) so they hold under either OS colour scheme.
     `prism-important` belongs to the yellow group: the site declares it twice
     and its later rule wins. */
  .bbCodeCode .prism-token.prism-comment,
  .bbCodeCode .prism-token.prism-prolog,
  .bbCodeCode .prism-token.prism-doctype,
  .bbCodeCode .prism-token.prism-cdata {
    color: #8292a2 !important;
  }

  .bbCodeCode .prism-token.prism-constant,
  .bbCodeCode .prism-token.prism-tag,
  .bbCodeCode .prism-token.prism-italic {
    color: #f92672 !important;
  }

  .bbCodeCode .prism-token.prism-boolean,
  .bbCodeCode .prism-token.prism-number {
    color: #ae81ff !important;
  }

  .bbCodeCode .prism-token.prism-symbol,
  .bbCodeCode .prism-token.prism-atrule,
  .bbCodeCode .prism-token.prism-keyword,
  .bbCodeCode .prism-token.prism-selector,
  .bbCodeCode .prism-token.prism-function,
  .bbCodeCode .prism-token.prism-class-name,
  .bbCodeCode .prism-token.prism-important,
  .bbCodeCode .prism-token.prism-bold {
    color: #e6db74 !important;
  }

  .bbCodeCode .prism-token.prism-string,
  .bbCodeCode .prism-token.prism-attr-value,
  .bbCodeCode .prism-token.prism-attr-name,
  .bbCodeCode .prism-token.prism-char,
  .bbCodeCode .prism-token.prism-builtin {
    color: #a6e22e !important;
  }

  .bbCodeCode .prism-token.prism-regex,
  .bbCodeCode .prism-token.prism-variable,
  .bbCodeCode .prism-token.prism-package {
    color: #fd971f !important;
  }

  .bbCodeCode .prism-token.prism-deleted {
    color: #ff7b72 !important;
  }

  .bbCodeCode .prism-token.prism-inserted {
    color: #7ee787 !important;
  }

  /* ============================================================
     Case Mod Gallery ( /gallery/ )

     A separate stylesheet (gallery-*.css) the rest of the theme never
     reached: the index (`.gallery-index`) and the case page (`.casemod`)
     ship their own white cards, chips and rating widgets. `.casemod` is the
     one part of TechPowerUp with a custom-property layer, so remap its six
     tokens at the source and only hard-code the surfaces it paints literally.
     ============================================================ */

  .casemod {
    --accent: #5fb0e6;
    --line: #2d333b;
    --muted: #8b949e;
    --hdr: #cfe2f3;
  }

  /* ---- Gallery index: filter bar + facet chips ---- */
  .gallery-index .search-new {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  .gallery-index .facet-bar-label,
  .gallery-index .filter-list-item-entry-count {
    color: #8b949e !important;
  }

  .gallery-index .facet-chip {
    background-color: #21262d !important;
    border-color: #2d333b !important;
    color: #5fb0e6 !important;
  }

  .gallery-index .facet-chip.is-active,
  .gallery-index .facet-chip:hover {
    background-color: #2f74c0 !important;
    border-color: #2f74c0 !important;
    color: #ffffff !important;
  }

  /* Selected value inside an open facet picker — the site marks it with a pale
     #ebeff2 plate, the only thing separating it from its unselected siblings. */
  .gallery-index .filter-options > a.is-selected {
    background-color: #21303f !important;
    border-color: #2f74c0 !important;
  }

  /* Hovering a selected value turns it red and swaps its label for a ✕ — that
     is the only "click to remove" affordance, so the rule above must not eat it. */
  .gallery-index .filter-options > a.is-selected:hover {
    background-color: #711a1a !important;
    border-color: #a03a3a !important;
  }

  .gallery-index .filter-options-nothing-found {
    color: #f0a0a0 !important;
  }

  /* The "you must be registered" notice is a #fd5 identity plate; only its ink
     was broken — the sitewide light body colour landed white-on-yellow. */
  .gallery-index .addcase-button,
  .gallery-index .addcase-button * {
    color: #4a3a00 !important;
  }

  .gallery-index .addcase-button a {
    color: #1f4e79 !important;
  }

  /* Image well behind each tile photo (site paints it flat `gray`) */
  .gallery-index .gallery-box > a {
    background-color: #21262d !important;
  }

  /* Tile hover flips the card to #eee with a #ddd outline — nothing in the
     theme reads `outline`, so every hovered tile drew a bright ring. */
  .gallery-index .gallery-box:hover {
    background-color: #1c2128 !important;
    outline-color: #2d333b !important;
  }

  /* Tile description (#444) and byline (#777) were dark-on-dark */
  .gallery-index .gallery_box_text,
  .gallery-index .gallery_box_info {
    color: #8b949e !important;
  }

  /* Comments heading names the case in a #458 <i>/<a> — 2.1:1 on the dark page */
  .comments > h2 > span > i,
  .comments > h2 > span > a {
    color: #5fb0e6 !important;
  }

  /* ---- Case page ( .casemod ) ---- */
  .casemod .casenav .button-group {
    background-color: transparent !important;
  }

  /* The 2px accent frame is what marks the score card out from the plain
     panels around it; the blanket border reset greys it, and --accent alone
     cannot win against an !important rule. */
  .casemod .ratebox {
    background-color: #1c2128 !important;
    background-image: none !important;
    border-color: #2f74c0 !important;
    box-shadow: none !important;
  }

  /* The rating summary's score is a <span>, so the sitewide span ink beats
     `color: var(--accent)` and the number reads as plain body text. */
  .casemod .rs-num {
    color: #5fb0e6 !important;
  }

  .casemod .kv,
  .casemod .other-projects ul,
  .casemod .linkpill {
    background-color: #1c2128 !important;
  }

  .casemod .kv dt,
  .casemod .lp-icon,
  .casemod .op-score,
  .casemod .rdist {
    background-color: #21262d !important;
  }

  .casemod .linkpill:hover .lp-icon,
  .casemod .other-projects a:hover,
  .casemod .showall:hover {
    background-color: #21303f !important;
  }

  /* Rating histogram: the #7d97c8 fill is the data and stays; the #dfe2e6
     "no votes at this score" stub and the 3px byline dot were light specks. */
  .casemod .rdc-zero,
  .casemod .byline .dot {
    background-color: #30363d !important;
  }

  .casemod .rdc:hover .rdc-zero {
    background-color: #444c56 !important;
  }

  .casemod .rdc:hover .rdc-num {
    color: #e6edf3 !important;
  }

  /* ============================================================
     DRAM Latency Calculator ( /dram-latency/ )

     Styled entirely from a page-local <style>, so nothing else in the theme
     claims it: the whole tool sits on an #f4f4f4 slab and every row label
     ("Data Rate", "Latency", "ns") is sitewide body ink, i.e. white-on-white.
     ============================================================ */

  .dram-latency-form {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  /* Spinner arrows are a background-image SVG whose <polygon> carries no
     `fill`, so it renders BLACK — invisible once the input goes dark. Restate
     the same two triangles in the theme's ink; geometry (16px, centred,
     no-repeat) is inherited from the site's own rule. */
  .number-input-button {
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'%3E%3Cpolygon points='8,11 13,6 3,6' fill='%23c4cdd6'/%3E%3C/svg%3E") !important;
  }

  .number-input-button.number-up {
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 16 16'%3E%3Cpolygon points='8,5 13,10 3,10' fill='%23c4cdd6'/%3E%3C/svg%3E") !important;
  }

  .number-input-button:hover {
    background-color: #2d333b !important;
  }

  /* A locked field is marked by a pale cream plate — the only signal that the
     value is derived rather than editable. Keep the amber, dark. */
  .number-input input:disabled {
    background-color: #332d1a !important;
    color: #e3c46a !important;
  }

  /* ============================================================
     Computer Trivia ( /trivia/ )

     The live message log colour-codes every row by KIND, so the tints are
     signal, not decoration — keep the five hues and only take them dark.
     ============================================================ */

  .trivia .messagecontainer > #messages > .connection {
    background-color: #21262d !important;
  }

  .trivia .messagecontainer > #messages > .question {
    background-color: #16242e !important;
  }

  .trivia .messagecontainer > #messages > .solved {
    background-color: #332d1a !important;
  }

  .trivia .messagecontainer > #messages > .notice {
    background-color: #2a1e33 !important;
  }

  .trivia .messagecontainer > #messages > .chat {
    background-color: #17251a !important;
  }

  .trivia > .score > #score {
    color: #e6edf3 !important;
  }

  /* ============================================================
     Live event coverage ( /live/ , tpulive-*.css )
     ============================================================ */

  .tpulive-files .imageitem {
    background-color: #1c2128 !important;
  }

  .tpulive-events .eventlist {
    background-color: #1c2128 !important;
  }

  /* Coverage-progress markers: red / blue / green is the whole message, and
     the site's `#00f` and `green` are both under 3:1 on a dark page. */
  .tpulive-files .categories .status-incomplete {
    color: #ff7b72 !important;
  }

  .tpulive-files .categories .status-partial {
    color: #79c0ff !important;
  }

  .tpulive-files .categories .status-complete {
    color: #3fb950 !important;
  }

  /* Event announcement banner (#fef89c) — keep the amber signal, take it dark */
  .tpulive-files .announcement {
    background-color: #332d1a !important;
    color: #e3c46a !important;
  }

  .tpulive-files .announcement table th {
    color: #c9b68a !important;
  }

  /* News live-blogs: the "just updated" flash (#dbffdb) and the standing info
     panel (#dbedff, dark navy ink) are the only two tinted news surfaces. */
  .newspost > .text > .live-blog-updated--highlight {
    background-color: #17251a !important;
  }

  .newspost > .live-blog-info {
    background-color: #16242e !important;
    color: #9bd4ff !important;
  }

  /* ============================================================
     Fancybox image lightbox (news photos, live coverage, gallery)

     Its prev/next/close are `<button>`s that the site keeps as TRANSPARENT
     hit-areas carrying only a background-image glyph, so the generic button
     rule above did both halves of the damage: a #21262d plate ~190px wide over
     the photo, and `background-image: none` erasing the arrows outright —
     the lightbox had no visible navigation at all. Reclaim the transparency
     and restate the three glyphs in the theme's ink (their size/position stay
     the site's). `opacity: .3`, and 1.0 on hover, is the site's own affordance.
     ============================================================ */

  .fancybox-container .fancybox-tpu-btn {
    background-color: transparent !important;
  }

  .fancybox-container .fancybox-tpu-btn-prev {
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 256 256'%3E%3Cpath d='M160 40 L72 128 L160 216' fill='none' stroke='%23e6edf3' stroke-width='26' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E") !important;
  }

  .fancybox-container .fancybox-tpu-btn-next {
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 256 256'%3E%3Cpath d='M96 40 L184 128 L96 216' fill='none' stroke='%23e6edf3' stroke-width='26' stroke-linecap='round' stroke-linejoin='round'/%3E%3C/svg%3E") !important;
  }

  .fancybox-container .fancybox-tpu-btn-close {
    background-image: url("data:image/svg+xml;charset=utf8,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 256 256'%3E%3Cpath d='M56 56 L200 200 M200 56 L56 200' fill='none' stroke='%23e6edf3' stroke-width='26' stroke-linecap='round'/%3E%3C/svg%3E") !important;
  }

  /* Shown in place of the photo when an ad blocker kills the request */
  .fancybox-error {
    background-color: #1c2128 !important;
  }

  .fancybox-error p {
    color: #c4cdd6 !important;
  }

  /* ============================================================
     PhotoSwipe image lightbox ( /gallery/ case pages )

     The case-mod gallery runs PhotoSwipe (js/photoswipe/), not Fancybox — the
     two coexist, Fancybox still serving /live/ coverage. PhotoSwipe is already
     a dark lightbox; its close / zoom / prev / next are transparent hit-areas
     wrapping an inline SVG icon, so the generic button rule stamps a #21262d
     plate and a border on each one — two 75×100 slabs beside the photo and a
     50×60 pair in the toolbar. Only the plate is wrong; the icons carry their
     own white fill. Hover is icon-opacity in PhotoSwipe, never a plate, so the
     hover state has to be named or the generic `button:hover` re-fills it.
     ============================================================ */

  .pswp .pswp__button,
  .pswp .pswp__button:hover {
    background-color: transparent !important;
    border: 0 !important;
  }

  /* ---- Footer ----
     `<footer>` is a CONTENT tag here as much as page chrome: TPU wraps every news
     comment's timestamp row, the review article's bottom page-nav strip and the
     front-page poll's vote bar in a bare `<footer>`, so a tag-level plate cuts a
     near-black band through three in-page components. Match the footer CLASSES. */
  footer.site-footer,
  #footer,
  .page-footer,
  .footer,
  .p-footer {
    background-color: #0d1117 !important;
    color: #8b949e !important;
    border-top: 1px solid #21262d !important;
  }

  footer.site-footer a,
  #footer a,
  .p-footer a {
    color: #8b949e !important;
  }

  footer.site-footer a:hover,
  #footer a:hover,
  .p-footer a:hover {
    color: #c4cdd6 !important;
  }

  /* ============================================================
     XenForo forums ( /forums/ )
     ============================================================ */

  .p-body,
  .p-body-inner,
  .p-pageWrapper,
  .p-body-main,
  .p-body-content {
    background-color: transparent !important;
    color: #c4cdd6 !important;
  }

  .p-header,
  .p-header-inner {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
  }

  /* Forum logo is a scheme-dependent <picture>: dark-OS loads logo-white-v25.png
     (a WHITE "TECH"/"UP" wordmark, already built for a dark bar) and light-OS
     loads logo-v25.png (a BLACK wordmark, for the native light bar). Our header
     is ALWAYS dark, so branch on the same prefers-color-scheme the <picture>
     keys off: leave the white asset untouched, and invert the black one
     (black → white, hue-rotate/saturate keep the red "POWER" button red).
     The news-site `.page-header__logo` is a single black-wordmark SVG bg-image
     and keeps its own always-on invert filter above. */
  @media (prefers-color-scheme: dark) {
    .p-header-logo img {
      filter: none !important;
    }
  }

  @media (prefers-color-scheme: light) {
    .p-header-logo img {
      filter: invert(1) hue-rotate(180deg) saturate(4) brightness(0.92) !important;
    }
  }

  .p-sectionLinks,
  .p-breadcrumbs,
  .p-description {
    background-color: #161d27 !important;
    color: #c4cdd6 !important;
    border-color: #21262d !important;
  }

  /* Selected top-nav tab: the light style paints the active `.p-navEl` a #f5f5f5
     pill (a bright block on the dark bar for a light-OS user). Give it the
     nav-hover navy so "you are here" reads as an accent, not a white plate. */
  .p-navEl.is-selected,
  .p-navEl.is-selected .p-navEl-link {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* The MOBILE off-canvas nav marks the current section on a different node than
     the desktop bar (`.offCanvasMenu-linkHolder.is-selected`, not `.p-navEl`), so
     the desktop rule above misses it and it shipped as a white #f5f5f5 slab across
     the dark drawer. Only a narrow viewport ever renders this. */
  .offCanvasMenu-linkHolder.is-selected {
    background-color: #21303f !important;
  }

  /* Guest / info notice banner (the "Welcome to TechPowerUp Forums, Guest!" bar)
     ships as a #e8f4fc light-blue block; restyle as our dark info panel. */
  .notice,
  .notice--block,
  .notices .notice {
    background-color: #16242e !important;
    border-color: #2970a3 !important;
    color: #c4cdd6 !important;
  }

  /* Collapsed contentRow fade-out is a `linear-gradient(transparent, #fff)` mask
     that bleeds white over the truncated preview; retint to the card colour.
     The sidebar block footer carries a light #f5f5f5→#fafafa gradient too. */
  .contentRow-fader {
    background-image: linear-gradient(rgba(28, 33, 40, 0), #1c2128 80%) !important;
  }

  /* Its own ink is the light style's `--xf-blockFooterTextColor` #4f4f4f, a
     direct declaration that beats the light body colour our .block rules
     inherit down, so the footer note ("Totals may include hidden visitors.",
     "Emoji provided by JoyPixels.") lands at 2.1:1 on the dark plate.
     `.u-dimmed` / `.menu-footer` are the same #4f4f4f token on other surfaces. */
  .block-footer,
  .menu-footer,
  .u-dimmed {
    color: #8b949e !important;
  }

  .block-footer,
  .menu-footer {
    background-color: #161d27 !important;
    background-image: none !important;
  }

  .u-textColor {
    color: #c4cdd6 !important;
  }

  /* Content blocks / cards */
  .block,
  .block-container,
  .block-body,
  .block-row,
  .block-minorHeader,
  .blockMessage,
  .structItem,
  .structItemContainer {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
    border-color: #262c33 !important;
  }

  .block-row {
    background-color: transparent !important;
  }

  .block-header,
  .block-tabHeader,
  .structItem-cell--main .structItem-title {
    background-color: #161d27 !important;
    color: #e6edf3 !important;
  }

  /* XenForo paints its heading BANDS with a `linear-gradient(0deg, #e8f4fc, #fff)`
     background-IMAGE, so the background-COLOR reads transparent and no colour-only
     override clears them. `.overlay-title` is handled further down; the same gradient
     also carries the thread-list "Filters" bar and every popup menu's header and tab
     strip — all of which shipped as white bands with our near-white heading text.
     `.filterBar-menuTrigger` keeps a pale plate of its own while its menu is open. */
  .block-filterBar,
  .menu-header,
  .menu-tabHeader {
    background-color: #161d27 !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }

  .filterBar-filterToggle,
  .filterBar-menuTrigger.is-menuOpen,
  .filterBar-menuTrigger:hover {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* The remaining members of the same --xf-contentHighlightBg family: hover and
     selected states that no rule above claims, so each still flashes the light
     style's #e8f4fc plate. The menu/autocomplete rows also re-assert the dark
     --xf-textColor ink the site pins on them. */
  .menu-row--highlighted,
  .menu-row--clickable:hover,
  .autoCompleteList > li.is-selected {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  .formRow-linkList > li > a:hover,
  .actionBar-action--mq.is-selected,
  .actionBar-action--view:hover,
  .blockLinkSplitToggle:hover,
  .blockLinkSplitToggle.is-selected {
    background-color: #21303f !important;
  }

  /* Notable-members page (/forums/members/): the column footers
     (.memberOverviewBlock-seeMore) ship a #f5f5f5 plate and the selected sidebar
     nav row is XenForo's #e8f4fc `.blockLink.is-selected` highlight (the light
     style's, so a light-OS user sees a white bar). Match the block footer + nav
     hover tones. */
  .memberOverviewBlock-seeMore {
    background-color: #161d27 !important;
  }

  .blockLink:hover,
  .blockLink.is-selected {
    background-color: #21303f !important;
    color: #ffffff !important;
  }

  /* The selected row's 3px left "you are here" bar is the accent, not a surface
     border; the blanket `*` border reset greys it into the navy plate. */
  .blockLink.is-selected {
    border-left-color: #5fb0e6 !important;
  }

  /* XenForo's remaining `--xf-contentAltBg` (#f5f5f5) chips and panels. None is
     claimed by a rule above, so under a light OS each renders a near-white plate
     carrying our pale ink. `.bbCodeDemoBlock-item dd` is the BB-code help page's
     example/output column (~30 white slabs down the page, its sample text at
     1.1:1) and `.smilieText` the smilie-code pills beside it. */
  .bbCodeDemoBlock-item dd,
  .smilieText,
  .tagItem,
  .reactionScore,
  .likesBar,
  .bbMediaWrapper-fallback,
  .blockStatus,
  .filterBlock,
  .block-minorTabHeader {
    background-color: #21262d !important;
    background-image: none !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .smilieText:hover,
  .tagItem:hover,
  .reactionScore:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }

  /* A form's inline validation error and the post-action toast keep the light
     style's pale plate + near-black ink; retint to the alert palette so the
     error still reads as an error. */
  .inputValidationError {
    background-color: #2d1a1a !important;
    border-color: #7d2a2c !important;
    color: #ff7b72 !important;
  }

  .flashMessage {
    background-color: #21262d !important;
    color: #e6edf3 !important;
  }

  /* Narrow-viewport sidebar drawer: the `--blocks` variant paints its own
     #e8e8e8 shell and #e8f4fc header, neither of which the `--nav` drawer rules
     above reach. */
  .offCanvasMenu--blocks .offCanvasMenu-content {
    background-color: #1c2128 !important;
    color: #c4cdd6 !important;
  }

  .offCanvasMenu--blocks .offCanvasMenu-header {
    background-color: #161d27 !important;
    color: #e6edf3 !important;
  }

  /* Node listing (forum index) */
  .node {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  .node-body {
    background-color: transparent !important;
  }

  .node-title a,
  .structItem-title a {
    color: #cfe2f3 !important;
  }

  .node-description,
  .node-extra,
  .node-stats,
  .structItem-minor,
  .structItem-parts {
    color: #8b949e !important;
  }

  /* Posts / messages */
  .message,
  .message-inner,
  .message--post,
  .message--article {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  .message-cell--user,
  .message-user {
    background-color: #161d27 !important;
    border-color: #21262d !important;
  }

  .message-cell--main,
  .message-main,
  .message-content {
    background-color: transparent !important;
  }

  /* Narrow viewports stack the user cell above the post and join them with a
     CSS-triangle pointer: an outer border-toned triangle on the element and an
     inner post-toned one on its ::after, each three transparent sides plus one
     coloured. The blanket border reset fills all eight, turning the pointer into
     a solid grey block; only a narrow viewport renders it at all. */
  .message-userArrow {
    border-color: transparent transparent #2d333b !important;
  }

  .message-userArrow::after {
    border-color: transparent transparent #1c2128 !important;
  }

  .message-userContent,
  .bbWrapper {
    color: #c4cdd6 !important;
  }

  .message-name a,
  .username {
    color: #cfe2f3 !important;
  }

  /* XenForo colours usernames by member group — administrator red, moderator
     blue, super-moderator green and a staff blue. The broad `span` / `.username`
     rules above flattened every group to one grey, so a staff/mod name in the
     members-online list (a bare span, no title beside it) read LESS prominent
     than a regular blue link. Re-assert the group colours with fixed bright
     values: the forum now serves a native DARK style under prefers-color-scheme
     dark, so `hsl(var(--xf-userTitleColor*))` resolved to the *light* style's
     dark navy/green for a light-OS user (dark-on-dark, invisible). Bake the
     readable hues instead — they stay correct in both native schemes. */
  .username--staff {
    color: #79c0ff !important;
  }

  .username--style3 {
    color: #ff7b72 !important;
  }

  .username--style4 {
    color: #79c0ff !important;
  }

  .username--style24 {
    color: #3fb950 !important;
  }

  /* Thread-prefix / node labels ship a plate with a coloured label; the broad
     `label` rule greyed the "primary" (blue) variant's text, and the light
     style's #e8f4fc plate survived on a light-OS user. Repaint both. */
  .label--primary {
    background-color: #21303f !important;
    color: #79c0ff !important;
  }

  /* The other XenForo prefix-label colour variants (e.g. the orange "OFFICIAL"
     flag) keep their bright light-style plate — a #ffcc00 pill with low-contrast
     ink on the dark forum. Only `.label--primary` was themed above; give each
     remaining semantic variant a dark tint + readable ink, matching the alert
     palette so the prefix's meaning (info/success/warning/danger) survives. */
  .label--royalBlue,
  .label--skyBlue,
  .label--accent {
    background-color: #21303f !important;
    color: #79c0ff !important;
  }

  .label--green,
  .label--olive {
    background-color: #182a1a !important;
    color: #7ee787 !important;
  }

  .label--red,
  .label--pink,
  .label--hotPink {
    background-color: #2d1a1a !important;
    color: #ff7b72 !important;
  }

  .label--orange,
  .label--yellow {
    background-color: #2b2412 !important;
    color: #e3c46a !important;
  }

  .label--purple,
  .label--deepPurple {
    background-color: #2a1e33 !important;
    color: #d2a8ff !important;
  }

  .label--grey,
  .label--lightGrey,
  .label--subtle,
  .label--silver {
    background-color: #21262d !important;
    color: #c4cdd6 !important;
  }

  .label--lightGreen {
    background-color: #182a1a !important;
    color: #7ee787 !important;
  }

  .label--error {
    background-color: #2d1a1a !important;
    color: #ff7b72 !important;
  }

  /* User banners under a username are `<a>` (or `<span>`) elements, so the blanket
     `a:link` (0,1,1) and `span` (0,0,1) colour rules above beat every banner's own
     ink — both the class variants' (XenForo sets those WITHOUT !important) and the
     custom ones' (a usergroup sets plate + ink INLINE). TPU's gold Patreon
     "Supporter" banner therefore rendered link-blue on pale gold at ~1.6:1.
     Each XenForo colour variant gets the tint its `.label--*` twin already has, at
     two classes so it outranks `a:link`. A CUSTOM banner keeps its inline identity
     plate and takes a dark ink that reads on it — which assumes the pale plate TPU
     ships; its inline border-color is greyed by the blanket `*` reset, so follow the
     ink instead. Both custom rules are (0,1,1), i.e. they tie `a:link` and win only
     because this block is later in the sheet. */
  a.userBanner,
  span.userBanner {
    color: #3d2f05 !important;
    border-color: currentColor !important;
  }

  .userBanner.userBanner--staff,
  .userBanner.userBanner--primary,
  .userBanner.userBanner--accent,
  .userBanner.userBanner--blue,
  .userBanner.userBanner--royalBlue,
  .userBanner.userBanner--skyBlue {
    background-color: #16242e !important;
    border-color: #2970a3 !important;
    color: #79c0ff !important;
  }

  .userBanner.userBanner--green,
  .userBanner.userBanner--olive,
  .userBanner.userBanner--lightGreen {
    background-color: #182a1a !important;
    border-color: #2a5c2d !important;
    color: #7ee787 !important;
  }

  .userBanner.userBanner--red,
  .userBanner.userBanner--pink,
  .userBanner.userBanner--hotPink {
    background-color: #2d1a1a !important;
    border-color: #7d2a2c !important;
    color: #ff7b72 !important;
  }

  .userBanner.userBanner--orange,
  .userBanner.userBanner--yellow {
    background-color: #2b2412 !important;
    border-color: #6b5a12 !important;
    color: #e3c46a !important;
  }

  .userBanner.userBanner--purple,
  .userBanner.userBanner--deepPurple {
    background-color: #2a1e33 !important;
    border-color: #4c3a5e !important;
    color: #d2a8ff !important;
  }

  .userBanner.userBanner--gray,
  .userBanner.userBanner--silver {
    background-color: #21262d !important;
    border-color: #2d333b !important;
    color: #c4cdd6 !important;
  }

  .message-userTitle,
  .userTitle {
    color: #8b949e !important;
  }

  .message-attribution,
  .message-attribution-main,
  .message-attribution-opposite,
  .message-lastEdit,
  .message-signature {
    color: #8b949e !important;
    border-color: #21262d !important;
  }

  /* Quotes inside posts */
  blockquote,
  .bbCodeBlock--quote,
  .bbCodeBlock-title {
    background-color: #161d27 !important;
    color: #c4cdd6 !important;
    border-color: #2d333b !important;
  }

  /* The quote attribution row is an accent in both of the forum's own schemes
     (#d48311 dark / #f2930d light), not body ink; the shared rule above would
     sink it into the quoted text. The username inside stays an `a:link` blue. */
  .bbCodeBlock-title {
    color: #e3a008 !important;
  }

  /* Action bar (reactions / reply) */
  .actionBar,
  .actionBar-set {
    background-color: transparent !important;
  }

  /* The reactions strip's 2px left rule is XenForo's #2970a3 accent, not a
     surface border; the blanket `*` border-color pass above greys it out.
     The strip itself + its per-reaction summary chips ship a #f5f5f5 light
     footer band (the light forum style), so paint them onto the post. */
  .reactionsBar {
    background-color: #161d27 !important;
    border-left-color: #2970a3 !important;
  }

  .reactionSummary li,
  .reactionsBar .reactionSummary li {
    background-color: transparent !important;
  }

  /* Members with no uploaded photo get a generated letter tile whose plate AND
     ink XenForo writes INLINE per user (`background-color:#66cccc; color:#206060`
     — a pastel plate with a darkened same-hue initial). Our blanket `a:link`
     !important beats the inline `color`, so the initial renders our link blue at
     ~1.2:1 on the plate, and the plate stays a bright pastel square (125px on a
     post, 48px on mobile). The generated palette spans #66cccc to #1f7a3d, so no
     single ink works across it — replace the whole chip with the neutral button
     tone. Match the site's own three-class chain so we also outrank its
     `--text` rule (0,3,0 !important) that resolves from light-style vars.
     The OP badge keeps its own darkened-hue ::before background. */
  .avatar.avatar--default.avatar--default--dynamic,
  .avatar.avatar--default.avatar--default--text,
  .avatar.avatar--default.avatar--default--image {
    background-color: #21262d !important;
  }

  .avatar.avatar--default.avatar--default--dynamic,
  .avatar.avatar--default.avatar--default--text {
    color: #c4cdd6 !important;
  }

  /* Avatar online-status marker: a #f5f5f5 ring around a green ::before dot;
     retint the ring to the user-cell colour so only the green dot reads. */
  .message-avatar-online {
    background-color: #161d27 !important;
  }

  /* Forum pagination (XenForo `.pageNav`): the page pills + prev/next jumps ship
     a #e8f4fc light-blue plate and the current page a #fef4e7 amber one, none
     covered by the news-site `.pager` rules. Match the site's dark button tone
     and keep the current page on our blue accent. */
  .pageNav-page,
  .pageNav-jump {
    background-color: #21262d !important;
    border-color: #2d333b !important;
  }

  .pageNav-page a,
  .pageNav-jump {
    color: #d6e2ee !important;
  }

  .pageNav-page:hover,
  .pageNav-jump:hover {
    background-color: #2d333b !important;
  }

  /* Ties `.pageNav-page:hover` above on specificity and wins on source order —
     without the `:hover` half the current page loses its fill under the pointer
     and only the accent border is left to mark it. */
  .pageNav-page--current,
  .pageNav-page--current:hover {
    background-color: #2563a8 !important;
    border-color: #2f74c0 !important;
  }

  .pageNav-page--current,
  .pageNav-page--current a {
    color: #ffffff !important;
  }

  /* NARROW viewports swap the numbered `.pageNav` for `.pageNavSimple` — a set of
     pills the desktop rules never touch: the current one is a #fef4e7 cream plate
     and Next/Last carry a `linear-gradient(0deg, #e8f4fc, #fff)` background-IMAGE
     (bg-COLOR reads transparent, so a colour-only scan sees nothing). */
  .pageNavSimple-el {
    background-color: #21262d !important;
    background-image: none !important;
    color: #d6e2ee !important;
    border-color: #2d333b !important;
  }

  .pageNavSimple-el--current {
    background-color: #2563a8 !important;
    color: #ffffff !important;
    border-color: #2f74c0 !important;
  }

  /* Thread-list mini page-jump pills ("2", "3" next to a title): a #f5f5f5
     white plate the pageNav rules don't reach, so it shipped as a bright
     speck with our light-blue link text on white. Match the button tone. */
  .structItem-pageJump a {
    background-color: #21262d !important;
    color: #d6e2ee !important;
    border-color: #2d333b !important;
  }

  .structItem-pageJump a:hover {
    background-color: #2d333b !important;
    color: #ffffff !important;
  }

  .actionBar-action {
    color: #8b949e !important;
  }

  .actionBar-action:hover {
    color: #9bd4ff !important;
  }

  /* Tabs / data lists */
  .tabs,
  .tabs-tab,
  .dataList,
  .dataList-row,
  .dataList-cell {
    background-color: transparent !important;
    color: #c4cdd6 !important;
    border-color: #21262d !important;
  }

  .tabs-tab.is-active {
    color: #9bd4ff !important;
    border-color: #5fb0e6 !important;
  }

  /* Reply editor / rich text area */
  .fr-box .fr-wrapper,
  .fr-toolbar,
  .fr-element,
  .input--textarea {
    background-color: #0d1117 !important;
    color: #e6edf3 !important;
    border-color: #2d333b !important;
  }

  /* XenForo OVERLAY (the Log in / Register modal). None of this exists in the
     DOM until you click "Log in", so no load-time scan can reach it — and it
     shipped half-themed: a #e8e8e8 shell, a white-to-#e8f4fc title gradient, a
     #f5f5f5 label column beside our dark inputs, and #141414 body ink. */
  .overlay {
    background-color: #1c2128 !important;
    border-color: #2d333b !important;
  }

  .overlay-content,
  .overlay .blocks-textJoiner,
  .overlay .blocks-textJoiner em {
    color: #c4cdd6 !important;
  }

  .overlay-title {
    background-color: #161d27 !important;
    background-image: none !important;
    color: #e6edf3 !important;
    border-color: #262c33 !important;
  }

  /* The form's left LABEL column is a light plate, not a text colour */
  .formRow > dt,
  .formRow-label {
    background-color: #161d27 !important;
    color: #c4cdd6 !important;
  }

  /* The bar behind the submit button is an ABSOLUTELY POSITIONED sibling
     (`.formSubmitRow-bar`, rgba(232,244,252,.9)) — it is not an ancestor of
     anything, so an elementFromPoint/ancestor walk never sees it. */
  .formSubmitRow-bar {
    background-color: #161d27 !important;
  }

  /* `.inputGroup-text` is the affordance welded to an input: the password
     "Show" toggle and the share flyout's copy-link button. Both ship #fafafa. */
  .inputGroup-text,
  .shareInput-button {
    background-color: #21262d !important;
    color: #5fb0e6 !important;
    border-color: #2d333b !important;
  }

  /* Member tooltip (hover a username) and the full profile header: both are a
     `.memberProfileBanner` painted #e8f4fc, and every line in the tooltip
     (`.memberTooltip-blurb`: user title, trophy count, location) keeps the light
     style's #141414 ink, which turns dark-on-dark the moment the banner darkens.
     A member's uploaded banner is a background-IMAGE (the site's own rule gives
     the class `background-size: cover`), so it paints over this colour and is
     unaffected — only the default no-banner plate changes. */
  .memberTooltip-header,
  .memberProfileBanner {
    background-color: #161d27 !important;
  }

  /* Reaction / response strip under a post or profile post (--xf-contentAltBg,
     #f5f5f5 in the light style). `.reactionsBar` above is only one member of the
     family; the profile-post rows use `.message-responseRow` directly. */
  .message-responseRow {
    background-color: #161d27 !important;
  }

  .tooltip-content,
  .tooltip-content-inner,
  .memberTooltip,
  .memberTooltip-headerInfo,
  .memberTooltip-blurbContainer,
  .memberTooltip-blurb {
    color: #c4cdd6 !important;
  }

  /* Post attachment tiles ship a #f5f5f5 plate. An image attachment covers it
     (object-fit: cover), but a non-image file, a broken image and every
     lazy-load frame show the white square. */
  .attachmentList .file,
  .attachmentList .file--linked,
  .file-preview {
    background-color: #161d27 !important;
    border-color: #262c33 !important;
  }

  /* Collapsed quote / code blocks fade out under a `linear-gradient(rgba(245,
     245,245,0), #f5f5f5)` — a white wash over the truncated text. Retint each
     to the surface it actually sits on (quotes #161d27, code #0d1117). */
  .bbCodeBlock-expandLink {
    background-image: linear-gradient(rgba(13, 17, 23, 0), #0d1117 80%) !important;
  }

  .bbCodeBlock--quote .bbCodeBlock-expandLink {
    background-image: linear-gradient(rgba(22, 29, 39, 0), #161d27 80%) !important;
  }

  /* ============================================================
     Semantic / status colors — preserve meaning, tune for dark
     ============================================================ */

  .green,
  .label--green,
  .badge--green,
  span[style*="color: green"],
  .text-success {
    color: #3fb950 !important;
  }

  .red,
  .label--red,
  .badge--red,
  span[style*="color: red"],
  .text-error {
    color: #ff7b72 !important;
  }

  .orange,
  .label--orange,
  span[style*="color: orange"] {
    color: #e3a008 !important;
  }

  /* Bootstrap-style callouts (login/register errors, download notices) — the
     site ships pastel panels with matching dark ink. Keep the hue, invert the
     value. The `color: inherit` re-assert is needed because the broad
     `p, li, span` body rule would otherwise wash the ink to neutral grey. */
  .alert-success {
    background-color: #182a1a !important;
    border-color: #2a5c2d !important;
    color: #7ee787 !important;
  }

  .alert-info {
    background-color: #16242e !important;
    border-color: #2970a3 !important;
    color: #79c0ff !important;
  }

  .alert-warning {
    background-color: #2b2412 !important;
    border-color: #6b5a12 !important;
    color: #e3c46a !important;
  }

  .alert-danger {
    background-color: #2d1a1a !important;
    border-color: #7d2a2c !important;
    color: #ff7b72 !important;
  }

  .alert p,
  .alert li,
  .alert span,
  .alert h4 {
    color: inherit !important;
  }

  /* Remaining light cards on the low-traffic pages the document rule also
     claims: the awards page, press-kit media assets, the staff roster's zebra,
     and the trivia game's message log */
  .awards .award,
  .media-asset,
  .trivia .messagecontainer {
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
  }

  .staff-member:nth-child(odd) {
    background-color: #1c2128 !important;
  }

  /* ============================================================
     Firewall / bot-check interstitial

     TechPowerUp fronts the WHOLE domain — news, spec databases and
     /forums/ alike — with a proof-of-work firewall that replaces the
     requested page with a standalone document: one `main.card` panel,
     no site chrome, and its own palette keyed off prefers-color-scheme.
     Under a LIGHT OS that panel stays #fff while our sitewide ink is
     already light, so the heading and the status line render at ~1.2:1
     and the page reads blank. `main.card` exists on no other page of
     the site (probed across news, review, download, gallery, spec DB
     and the forum). The custom properties below are the page's own —
     overriding them here also reaches the progress-bar track and the
     drag-captcha rail, which it paints with an INLINE
     `background: var(--progress-bg)` no selector of ours can outrank.
     `--progress-fill` stays the page's green: it is the signal. */
  main.card {
    --bg: #14181d;
    --card: #1c2128;
    --text: #e6edf3;
    --muted: #8b949e;
    --border: #262c33;
    --progress-bg: #30363d;
    --btn-bg: #2f74c0;
    background-color: #1c2128 !important;
    border-color: #262c33 !important;
    box-shadow: 0 8px 24px rgba(0, 0, 0, 0.5) !important;
  }

  main.card h1,
  main.card p,
  main.card dt,
  main.card dd {
    color: #e6edf3 !important;
  }

  /* The panel's own footer + meta rows are muted text ON the card, with no plate
     and no rule above them */
  main.card footer,
  main.card dl.meta,
  main.card .muted {
    background-color: transparent !important;
    border-top: 0 !important;
    color: #8b949e !important;
  }

  main.card footer a {
    color: #5fb0e6 !important;
  }

  /* Selection */
  ::selection {
    background-color: #2f74c0 !important;
    color: #ffffff !important;
  }

  /* Horizontal rules / dividers */
  hr {
    border-color: #262c33 !important;
    background-color: #262c33 !important;
  }

  /* Scrollbar */
  * {
    scrollbar-color: #2d333b #14181d;
  }
}
